using System.Diagnostics;
using System.Text;
using System.Text.Json;
using TsRecommend;
namespace TsScheduler;
internal static class TsRenameSupport
{
 internal sealed record TextFile(string FileName,string EncodingName,string Text,int Lines,int TabLines);
 internal static TextFile Inspect(string path){byte[] bytes=File.ReadAllBytes(path);if(bytes.Length>1024*1024)throw new InvalidDataException("設定ファイルが大きすぎます（上限1MB）。");Encoding encoding;
  if(bytes.AsSpan().StartsWith(new byte[]{0xff,0xfe}))encoding=new UnicodeEncoding(false,true,true);else if(bytes.AsSpan().StartsWith(new byte[]{0xfe,0xff}))encoding=new UnicodeEncoding(true,true,true);else if(bytes.AsSpan().StartsWith(new byte[]{0xef,0xbb,0xbf}))encoding=new UTF8Encoding(true,true);else{try{encoding=new UTF8Encoding(false,true);encoding.GetString(bytes);}catch(DecoderFallbackException){encoding=Encoding.GetEncoding(932,EncoderFallback.ExceptionFallback,DecoderFallback.ExceptionFallback);}}
  string text=encoding.GetString(bytes).TrimStart('\ufeff');var lines=text.Replace("\r","").Split('\n').Where(s=>s.Length>0).ToArray();return new(Path.GetFileName(path),encoding.WebName,text,lines.Length,lines.Count(s=>s.Contains('\t')));
 }
 internal static string Diagnose(string executable){if(!File.Exists(executable))return "TsRename.exeを指定してください。";var version=FileVersionInfo.GetVersionInfo(executable);string folder=Path.GetDirectoryName(Path.GetFullPath(executable))!;var result=new StringBuilder();result.AppendLine("本体："+Path.GetFileName(executable));result.AppendLine("バージョン："+(string.IsNullOrWhiteSpace(version.FileVersion)?"情報なし":version.FileVersion));
  string candidate=Path.Combine(folder,"ChSet3.txt");result.AppendLine("同じフォルダーのChSet3.txt："+(File.Exists(candidate)?"あり":"なし"));if(File.Exists(candidate)){try{var file=Inspect(candidate);result.AppendLine($"文字コードの判定：{file.EncodingName} ／ 空行以外 {file.Lines}行 ／ タブ区切り {file.TabLines}行");}catch(Exception e)when(e is IOException or DecoderFallbackException){result.AppendLine("設定ファイルを確認できません："+e.Message);}}
  var ini=Directory.EnumerateFiles(folder,"*.ini").Where(p=>new FileInfo(p).Length<=1024*1024).Take(20);foreach(string path in ini){try{var file=Inspect(path);foreach(string line in file.Text.Split('\n').Where(l=>l.Contains("ChSet3",StringComparison.OrdinalIgnoreCase)))result.AppendLine(Path.GetFileName(path)+"："+line.Trim());}catch(IOException){}catch(DecoderFallbackException){}}
  if(File.Exists(candidate))result.AppendLine(ChSet3Compatibility.Diagnose(candidate));result.AppendLine();result.AppendLine("確認した配布版1.25は、起動時に本体と同じフォルダーのChSet3.txtを読みます。書式は局名・SID・TSID・ONID・種別・EPG対象・検索対象の7項目、タブ区切り・Shift_JIS・CRLFです。IDは10進数で、録画データの3つのIDと一致する必要があります。保存後はTsRenameを再起動してください。");return result.ToString();
 }
 internal static string StationReference(IEnumerable<KeyValuePair<int,string>> stations)=>"TVRock局ID\t局名\r\n"+string.Join("\r\n",stations.OrderBy(p=>p.Key).Select(p=>p.Key+"\t"+p.Value.Replace('\t',' ').Replace('\r',' ').Replace('\n',' ')))+"\r\n";
 internal static string Backup(string path,string home){string destination=Path.Combine(home,"tsrename-backups",DateTime.Now.ToString("yyyyMMdd-HHmmssfff")+"-"+Guid.NewGuid().ToString("N"));Directory.CreateDirectory(destination);string copy=Path.Combine(destination,Path.GetFileName(path));File.Copy(path,copy,false);return copy;}
}
internal sealed partial class MainForm
{
 void InitializeTsRenameSupport(FlowLayoutPanel body){var open=new Button{Text="TsRename連携を確認",AutoSize=true};body.Controls.Add(open);body.Controls.Add(DetailNote("TsRename本体・設定ファイル候補・局一覧を確認します。既存の設定や録画ファイルは自動変更しません。"));open.Click+=(_,_)=>ShowTsRenameSupport();}
 void ShowTsRenameSupport(){using var dialog=new Form{Text="TsRename連携の確認",Font=Font,ClientSize=new Size(820,620),MinimumSize=new Size(700,500),StartPosition=FormStartPosition.CenterParent};var shell=new TableLayoutPanel{Dock=DockStyle.Fill,ColumnCount=1,RowCount=3,Padding=new Padding(16)};shell.RowStyles.Add(new(SizeType.AutoSize));shell.RowStyles.Add(new(SizeType.Percent,100));shell.RowStyles.Add(new(SizeType.AutoSize));dialog.Controls.Add(shell);
  var toolbar=new FlowLayoutPanel{Dock=DockStyle.Top,AutoSize=true,WrapContents=true};var path=new TextBox{ReadOnly=true,Width=570,AccessibleName="TsRename本体の場所"};string setting=Path.Combine(RecommendationHome,"tsrename-path.json");try{path.Text=JsonSerializer.Deserialize<string>(File.ReadAllText(setting))??"";}catch{}
  var select=new Button{Text="本体を指定",AutoSize=true};toolbar.Controls.AddRange([path,select]);shell.Controls.Add(toolbar,0,0);var viewport=new ChromeScrollPanel{Dock=DockStyle.Fill};var report=new Label{AutoSize=true,MaximumSize=new Size(740,0),Padding=new Padding(0,12,0,12)};viewport.Controls.Add(report);viewport.SizeChanged+=(_,_)=>report.MaximumSize=new Size(Math.Max(200,viewport.ClientSize.Width-20),0);shell.Controls.Add(viewport,0,1);
  var actions=new FlowLayoutPanel{AutoSize=true,Dock=DockStyle.Bottom};var refresh=new Button{Text="診断を更新",AutoSize=true};var config=new Button{Text="設定候補を表示",AutoSize=true};var backup=new Button{Text="設定候補をバックアップ",AutoSize=true};var generate=new Button{Text="ChSet3.txtを作成",AutoSize=true};var export=new Button{Text="Zooの局一覧を保存",AutoSize=true};var close=new Button{Text="閉じる",AutoSize=true,DialogResult=DialogResult.Cancel};actions.Controls.AddRange([refresh,config,backup,generate,export,close]);shell.Controls.Add(actions,0,2);dialog.CancelButton=close;
  void Update(){try{report.Text=TsRenameSupport.Diagnose(path.Text);}catch(Exception e){report.Text=e.Message;}}string Candidate()=>Path.Combine(Path.GetDirectoryName(path.Text)??"","ChSet3.txt");
  select.Click+=(_,_)=>{using var file=new OpenFileDialog{Filter="TsRename (TsRename.exe)|TsRename.exe",CheckFileExists=true};if(file.ShowDialog(dialog)!=DialogResult.OK)return;path.Text=file.FileName;Directory.CreateDirectory(RecommendationHome);File.WriteAllText(setting,JsonSerializer.Serialize(path.Text));Update();};refresh.Click+=(_,_)=>Update();
  config.Click+=(_,_)=>{try{var file=TsRenameSupport.Inspect(Candidate());using var preview=new Form{Text=file.FileName+"（読み取り専用）",ClientSize=new Size(760,480),StartPosition=FormStartPosition.CenterParent};var view=new ChromeScrollPanel{Dock=DockStyle.Fill};view.Controls.Add(new Label{AutoSize=true,MaximumSize=new Size(720,0),Text=file.Text,Font=Font});preview.Controls.Add(view);preview.ShowDialog(dialog);}catch(Exception e){MessageBox.Show(dialog,e.Message,"設定候補を表示できません");}};
  backup.Click+=(_,_)=>{try{TsRenameSupport.Backup(Candidate(),RecommendationHome);report.Text+="\n設定候補のバックアップを保存しました。";}catch(Exception e){MessageBox.Show(dialog,e.Message,"バックアップできません");}};
  generate.Click+=(_,_)=>{ShowChSet3Generator(dialog,path.Text);Update();};
  export.Click+=(_,_)=>{try{using var file=new SaveFileDialog{Filter="局一覧（TSV）|*.tsv",FileName="TVRock-Zoo-局一覧.tsv",OverwritePrompt=true};if(file.ShowDialog(dialog)!=DialogResult.OK)return;var stations=Data.Tuners(Path.Combine(RockFolder,"dtv.ini")).Stations;File.WriteAllText(file.FileName,TsRenameSupport.StationReference(stations),new UTF8Encoding(true));report.Text+="\nZooの局一覧を保存しました。照合用の資料です。ChSet3.txtとしては使用できません。";}catch(Exception e){MessageBox.Show(dialog,e.Message,"局一覧を保存できません");}};Update();StyleControls(dialog);dialog.ShowDialog(this);
 }
}
